 const details=checks.map(x=>{const command=window.GpoComponents.manualCheck(state,h,x);return `<div class="endpoint-evidence"><strong>${esc(x.hostname)} · ${esc(x.state)}</strong><p>${esc(x.message||'')}</p><small>Actual value</small><pre>${esc(x.actualValue??'Unavailable')}</pre>${command?`<details class="manual-check-details"><summary>Manual check</summary><div class="manual-check-head"><small>${window.GpoUiDomain.isUserPolicy(h,state.settings)?'Run as the affected signed-in user':'PowerShell check on the recorded target'}</small><button type="button" data-copy-value="${esc(command)}">Copy</button></div><pre class="manual-check-command">${esc(command)}</pre></details>`:''}</div>`;}).join('');
